        require(address(this).balance >= depositAmount);
        c.Deposit{value: depositAmount}();

        uint beforeUser = c.balances(address(this));
        uint beforeContract = address(c).balance;

        bool reverted;
        try c.CashOut(cashOutAmount) {
            reverted = false;
        } catch {
