contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint depositAmount, uint cashOutAmount) public payable {
        uint balBefore = c.balances(address(this));
        c.Deposit{value: depositAmount}();
        uint balAfterDeposit = c.balances(address(this));
        bool depositIncreased = balAfterDeposit >= balBefore;
        bool depositCredited = balAfterDeposit == balBefore + depositAmount || depositAmount < 1 ether;
        require(depositIncreased);
        require(depositCredited);

        balBefore = c.balances(address(this));
        uint cBalBefore = address(c).balance;
        bool reverted;
        try c.CashOut(cashOutAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balAfter = c.balances(address(this));
        uint cBalAfter = address(c).balance;

        if (!reverted && cashOutAmount <= balBefore) {
            assert(balAfter == balBefore - cashOutAmount && cBalBefore >= cashOutAmount && cBalAfter == cBalBefore - cashOutAmount);
        } else {
            assert(balAfter == balBefore && cBalAfter == cBalBefore);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);
        uint minDeposit = c.MinDeposit();
        uint balBefore = c.balances(address(this));

        c.Deposit{value: depositAmount}();

        uint balAfter = c.balances(address(this));

        if (depositAmount >= minDeposit) {
            assert(balAfter == balBefore + depositAmount);
        } else {
            assert(balAfter == balBefore);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        uint minDeposit = c.MinDeposit();
        uint balBefore = c.balances(address(this));

        c.Deposit{value: depositAmount}();

        uint balAfter = c.balances(address(this));

        uint expectedDelta = depositAmount >= minDeposit ? depositAmount : 0;
        assert(balAfter == balBefore + expectedDelta);
    }
}

