                assert(address(c).balance == beforeContractBal);
                assert(address(this).balance == beforeSelfBal);
            }
        } catch {
            assert(depositAmount < minDeposit);
            assert(c.balances(address(this)) == beforeUserBal);
            assert(address(c).balance == beforeContractBal);
            assert(address(this).balance == beforeSelfBal);
