        require(depositAmount >= 1 ether);
        require(cashOutAmount <= depositAmount);

        c.Deposit{value: depositAmount}();
        uint beforeBalance = c.balances(address(this));
        require(beforeBalance == depositAmount);

        uint beforeEther = address(this).balance;
        uint cBeforeEther = address(c).balance;

        bool reverted;
        try c.CashOut(cashOutAmount) {
            reverted = false;
