            assert(afterBalance == beforeBalance - cashOutAmount);
            assert(cBeforeEther - cAfterEther == cashOutAmount);
        } else {
            assert(afterBalance == beforeBalance);
            assert(cAfterEther == cBeforeEther);
        }
    }

    receive() external payable {}
}

